CREATE TRIGGER secondary_go AFTER INSERT ON secondary BEGIN
  UPDATE clock SET n = n + 1; INSERT INTO run (arrival, parent, root, kind, cell, about, at, moment) VALUES (NEW.gate, NEW.run, NULL, 3, NEW.cell, NEW.about, (SELECT n FROM clock), strftime('%s', 'now')); UPDATE run SET root = coalesce((SELECT root FROM run WHERE id = NEW.run), id) WHERE id = (SELECT max(id) FROM run); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) VALUES ((SELECT max(id) FROM run), 19, 1, (SELECT max(id) FROM run)); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT (SELECT max(id) FROM run), 20, 1, NEW.run WHERE NEW.run IS NOT NULL;
  UPDATE secondary SET made = (SELECT max(id) FROM run), text = NULL WHERE id = NEW.id;
  INSERT INTO seq (run, pos, gate) SELECT (SELECT max(id) FROM run), key + 1, value FROM json_each(encode('main', NEW.text));
 INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT parent, cell, 1, id FROM run WHERE id = (SELECT max(id) FROM run) AND cell IS NOT NULL AND parent IS NOT NULL AND EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1); SELECT mother('CREATE TABLE IF NOT EXISTS main."' || about || '" (shard INTEGER PRIMARY KEY, before INTEGER, trigger INTEGER, call INTEGER, spawn INTEGER, times INTEGER); CREATE TABLE IF NOT EXISTS main."' || about || '.node" (id INTEGER PRIMARY KEY, source INTEGER, run INTEGER)') FROM run WHERE id = (SELECT max(id) FROM run) AND about IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pragma_table_info(about || '.node', 'main')); SELECT mother('INSERT INTO main."' || about || '.node" (source, run) VALUES (?, ?)', arrival, id) FROM run WHERE id = (SELECT max(id) FROM run) AND about IS NOT NULL AND EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1);
  SELECT mother('INSERT INTO main."' || about || '" (shard, before, trigger, call, spawn, times) SELECT (SELECT n + 1 FROM main.shards), 153, 68, NULL, 4554222, 0 WHERE NOT EXISTS (SELECT 1 FROM main."' || about || '"); UPDATE main.shards SET n = n + 1 WHERE (SELECT max(shard) FROM main."' || about || '") = n + 1') FROM run WHERE id = (SELECT max(id) FROM run) AND about IS NOT NULL AND EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1);
END
